\label{assumption:U}
There exist sets $U_k\in\mathfrak{B}$, $k\in\mathbb{N}$, such that
\begin{itemize}
\item[(i)] if $x\in U_k$, then $tx\in U_k$ for all $t\geq1$ 
(that is, $[1,\infty) U_k = U_k$);
\item[(ii)] the sets $V_k:=(0,\infty) U_k$, $k\in\mathbb{N}$, cover $\mathbb{X}$
(that is, $\bigcup_{k \in \mathbb{N}} V_k = \mathbb{X}$). 
\end{itemize}

\label{proposition:renorm}
Suppose that Assumption~\ref{assumption:U} holds.
The following are equivalent for a measure $\nu$ on $(\mathbb{X}, \mathfrak{B})$.
\begin{itemize}
\item[i)]
  The measure $\nu$ is a nontrivial $\alpha$-homogeneous measure with
  \begin{equation}
    \label{Eq:nu-finite}
    \nu(U_k)<\infty,\qquad k\in\mathbb{N}\,.
  \end{equation}
\item[ii)] The measure $\nu$ is the push-forward of the measure
  $\pi\otimes\theta_\alpha$ by the map $(x,t)\mapsto tx$, where
  $\pi$ is a probability measure on $\mathbb{X}$ such that
  \begin{equation}
    \label{eq:pi-Sk}
    \int_0^\infty \pi(tU_k)t^{\alpha-1} \, dt < \infty,\qquad k\in\mathbb{N},
  \end{equation}
  and $\theta_\alpha$ is the measure on $\mathbb{R}_{++}$ given by 
  $\theta_\alpha(dt) := \alpha t^{-(\alpha+1)} \, dt$.
\item[(iii)] For a probability measure $\pi$ on $\mathbb{X}$ such that
  \eqref{eq:pi-Sk} holds,
  \begin{equation}
    \label{Eq:nu-rep}
    \nu(B) = \alpha \int_0^\infty \pi(t B) \, t^{\alpha-1} \, dt
  \end{equation}
  for all $B \in \mathfrak{B}$.
\end{itemize}

