  \label{lemma:projection}
  Let $\nu$ be a $\sigma$-finite $\alpha$-homogeneous measure on
  $(\mathbb{X}, \mathfrak{B})$ and suppose that $\mathfrak{B}$ is $\nu$-complete.
  \begin{itemize}
  \item[i)] For $B \in \mathfrak{B}$ and a Borel set $I \subseteq \mathbb{R}_{++}$,
    the set $I B$ also belongs to $\mathfrak{B}$.
  \item[ii)] If $\nu([t,u) B) < \infty$ for $B \in \mathfrak{B}$ and $0 < t <
    u < \infty$, then $\nu([s,\infty) B) < \infty$ for all $s > 0$.
\end{itemize}

\label{assumption:X}
There exists $\mathbb{S}\in\mathfrak{B}$ such that 
\begin{displaymath}
  \mathbb{X}=\{tx:\; t\in\mathbb{R}_{++}, \, x\in\mathbb{S}\},
\end{displaymath}
and $\{x,tx\}\subset\mathbb{S}$ for some $x\in\mathbb{X}$ and $t>0$ implies that
$t=1$.

\label{thr:general-polar}
Suppose that Assumption~\ref{assumption:X} holds.  Let $\mathcal{H}$ be a
countable family of measurable functions $h:\mathbb{X}\mapsto\mathbb{R}_+$ such
that for all $h \in \mathcal{H}$ and $x \in \mathbb{X}$ the function $ t \mapsto
h(tx)$ is right-continuous (or left-continuous) on $\mathbb{R}_{++}$.

A $\sigma$-finite measure $\nu$ on $\mathbb{X}$ is $\alpha$-homogeneous and
satisfies
\begin{equation}
  \label{eq:nu-h-integral}
  \int_\mathbb{X} h(x) \, \nu(dx) <\infty,\qquad h\in\mathcal{H},
\end{equation}
and 
\begin{equation}
  \label{Eq:nu-support-h}
  \nu\left(\bigcap_{h\in\mathcal{H}} \{x\in\mathbb{X}:\; h(x)=0\}\right)=0
\end{equation}
if and only if there exists a probability measure $\pi$ on $\mathbb{X}$
such that \eqref{Eq:nu-rep} holds, 
\begin{equation}
  \label{Eq:levy-condition-pi-general}
  \int_{\mathbb{X}}\int_0^\infty h(tx) t^{-(\alpha+1)} \, dt \, \pi(dx) <\infty,
  \qquad h\in\mathcal{H},
\end{equation}
and 
\begin{displaymath}
  \pi\left((0,\infty) \bigcap_{h \in \mathcal{H}} \{x\in\mathbb{X}:\; h(x)=0\}\right)=0. 
\end{displaymath}

\begin{equation}
